import React from "react";

function Button({text,func}) {
  return (
    <button onClick={func} className=" border-2 w-full relative flex flex-row text-white border-yellow-400 p-2 text-lg hover:bg-yellow-400  hover:text-black hover:scale-110 hover:border-0 transition-all">
        <span className=" bg-white">..</span>
        {text}
    </button>
  );
}

export default Button;
